test("formatFoundKnowledge renders a clean empty message, not an error or empty string, matching list_knowledge's convention (issue #1008)", () => {
  assert.equal(formatFoundKnowledge([]), 'No knowledge entries found.');
});

test("formatFoundKnowledge renders each hit's #id with its match % (including a match below KNOWLEDGE_SEARCH_RELEVANCE_THRESHOLD, which knowledge_search would have excluded), in the order given — no relevance floor is applied here (issue #1008)", () => {
  const updatedAt = new Date('2026-01-01T00:00:00Z');
  const output = formatFoundKnowledge([
    { id: 42, title: 'Strong match', content: 'Strong content', similarity: 0.91, updatedAt },
    { id: 7, title: null, content: 'Weak content, no title', similarity: 0.12, updatedAt },
  ]);
  assert.ok(
    0.12 < KNOWLEDGE_SEARCH_RELEVANCE_THRESHOLD,
    'sanity: the weak fixture hit must genuinely sit below the relevance floor knowledge_search enforces',
  );
  const strongIdx = output.indexOf('#42 (91% match) Strong match: Strong content');
  const weakIdx = output.indexOf('#7 (12% match) Weak content, no title');
  assert.ok(strongIdx >= 0, 'the strong hit renders its id, match %, title and content');
  assert.ok(weakIdx >= 0, 'the weak, below-floor hit still renders — no relevance floor is applied');
  assert.ok(
    strongIdx < weakIdx,
    "hits render in the order given (searchKnowledge's similarity-descending order), not re-sorted",
  );
});

// formatFoundKnowledge citation/freshness notes (issue #1206): find_knowledge
// is the only knowledge-serving surface that receives the full
// KnowledgeCitationInfo shape on every hit but never rendered a citation
// note — this closes that parity gap by routing through the exact same
// formatKnowledgeCitationNote every other surface uses.
test('formatFoundKnowledge (issue #1206): a hit with sourceUnreachable === true renders the "⚠️ link appears dead" note, byte-identical in wording to formatKnowledgeCitationNote\'s output for the same hit rendered via formatKnowledgeSearchResults (knowledge_search)', () => {
  const checkedAt = new Date(Date.now() - 2 * 86_400_000);
  const hit = {
    id: 42,
    title: 'Old Page',
    content: 'Some content',
    similarity: 0.91,
    updatedAt: new Date(),
    autoGenerated: false,
    sourceUrl: 'https://example.org/old-page',
    sourceTitle: 'Old Page',
    verifiedAt: new Date(),
    lastRetrievedAt: null,
    sourceUnreachable: true,
    sourceCheckedAt: checkedAt,
  };
  const foundOutput = formatFoundKnowledge([hit], 0, 0);
  const searchOutput = formatKnowledgeSearchResults([{ ...hit, similarity: 0.91 }], 0, 0);
  const expectedNote = formatKnowledgeCitationNote(hit, 0, false, 0);
  assert.match(expectedNote, /⚠️ link appears dead/);
  assert.ok(
    foundOutput.includes(expectedNote),
    'find_knowledge must render the exact same dead-link note text formatKnowledgeCitationNote produces',
  );
  assert.ok(
    searchOutput.includes(expectedNote),
    'sanity: knowledge_search renders the same note text for the same hit, via the same shared formatter',
  );
});

test('formatFoundKnowledge (issue #1206): a hit with a live, non-auto-generated sourceUrl renders "source: <label> · last verified ~N ago"; a stale hit additionally renders the stale note — same notes, same order, as knowledge_search produces for the same hit', () => {
  const hit = {
    id: 7,
    title: 'Live Page',
    content: 'Ancient but still-cited content',
    similarity: 0.5,
    updatedAt: new Date(Date.now() - 400 * 86_400_000),
    autoGenerated: false,
    sourceUrl: 'https://docs.anthropic.com/en/api/messages',
    sourceTitle: 'docs: api/messages',
    verifiedAt: new Date(),
    lastRetrievedAt: null,
    sourceUnreachable: null,
    sourceCheckedAt: null,
  };
  const foundOutput = formatFoundKnowledge([hit], 30, 0);
  const expectedNote = formatKnowledgeCitationNote(hit, 30, false, 0);
  assert.match(
    expectedNote,
    /source: docs: api\/messages \(https:\/\/docs\.anthropic\.com\/en\/api\/messages\)/,
  );
  assert.match(expectedNote, /last verified/);
  assert.match(expectedNote, /may be outdated/);
  assert.ok(
    foundOutput.includes(`#7 (50% match) Live Page: Ancient but still-cited content`),
    'the existing id/match/title/content rendering is unchanged',
  );
  assert.ok(
    foundOutput.endsWith(expectedNote),
    'the note is appended after the existing line content, in order',
  );
});

test("formatFoundKnowledge (issue #1206): a hit with sourceUnreachable === null (never checked) and no other applicable note renders byte-identically to today's output — no false dead-link warning, no spurious source: line", () => {
  const updatedAt = new Date('2026-01-01T00:00:00Z');
  const hitWithoutCitationFields = {
    id: 42,
    title: 'Strong match',
    content: 'Strong content',
    similarity: 0.91,
    updatedAt,
  };
  const hitWithNullFields = {
    ...hitWithoutCitationFields,
    autoGenerated: false,
    sourceUrl: null,
    sourceTitle: null,
    verifiedAt: null,
    lastRetrievedAt: null,
    sourceUnreachable: null,
    sourceCheckedAt: null,
  };
  const outputWithoutFields = formatFoundKnowledge([hitWithoutCitationFields]);
  const outputWithNullFields = formatFoundKnowledge([hitWithNullFields]);
  assert.ok(
    outputWithoutFields.includes(
      `#42 (91% match) Strong match: Strong content (updated ${updatedAt.toISOString()})`,
    ),
  );
  assert.equal(
    outputWithoutFields,
    outputWithNullFields,
    'omitted vs explicit-null citation fields must render identically',
  );
  assert.doesNotMatch(outputWithoutFields, /link appears dead/);
  assert.doesNotMatch(outputWithoutFields, /source:/);
});

