// issue #1063: formatKnowledgeSearchResults' `lang` parameter now also
// selects the conflict caveat's language, not just the per-hit stale/
// low-rated caveats (#1038) — closing the one line #1038 named as a
// follow-up and deliberately left English-only.
test(
  "formatKnowledgeSearchResults renders the conflict caveat in te reo Māori when lang is 'mi', and stays " +
    "byte-identical to today's English KNOWLEDGE_CONFLICT_CAVEAT_TEXT when lang is 'auto'/omitted (issue #1063)",
  () => {
    const a = {
      title: 'A',
      content: 'Content A',
      similarity: 0.9,
      updatedAt: new Date(),
      autoGenerated: false,
      sourceUrl: null,
      sourceTitle: null,
      verifiedAt: null,
    };
    const b = { ...a, title: 'B', content: 'Content B', similarity: 0.8 };

    const withDefaultLang = formatKnowledgeSearchResults([a, b], undefined, undefined, true);
    assert.equal(
      withDefaultLang,
      formatKnowledgeSearchResults([a, b], undefined, undefined, true, undefined, 'auto'),
      "omitting lang must be byte-identical to passing 'auto' explicitly",
    );
    assert.match(
      withDefaultLang,
      new RegExp(`\\(${KNOWLEDGE_CONFLICT_CAVEAT_TEXT.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\)$`),
      "the default/'auto' rendering must stay byte-identical to today's English constant (regression guard)",
    );

    const withMiLang = formatKnowledgeSearchResults([a, b], undefined, undefined, true, undefined, 'mi');
    assert.match(
      withMiLang,
      new RegExp(`\\(${KNOWLEDGE_CONFLICT_CAVEAT_TEXT_MI.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\)$`),
      "lang: 'mi' must render the mi translation from the knowledgeConflictCaveat notice catalogue entry",
    );
    assert.notEqual(withMiLang, withDefaultLang, 'the mi rendering must differ from the English rendering');
  },
);

