test(
  're-running an identical confirmed team_setup call is idempotent: row counts are unchanged and every step reports already existed (issue #944)',
  { skip },
  async () => {
    const conv = `${RUN}-team-setup-idempotent`;
    const slug = `${RUN}-team-setup-idempotent`;
    const memberA = teamSetupMemberId();
    const memberB = teamSetupMemberId();

    const runOnce = async () => {
      const handler = teamSetupToolHandler('admin', { conversationId: conv });
      const result = await handler.handler({ slug, name: 'Idempotent Team', members: [memberA, memberB] });
      assert.equal(result.isError, false);
      const pending = takePendingAction('discord', conv, 'team-setup-admin-probe');
      assert.ok(pending);
      return pending?.execute();
    };

    const countRows = async () => {
      const { rows: p } = await pool.query(`SELECT id FROM projects WHERE slug = $1`, [slug]);
      const { rows: pm } = await pool.query(
        `SELECT count(*)::int AS n FROM project_members WHERE project_id = $1`,
        [p[0].id],
      );
      const { rows: ps } = await pool.query(
        `SELECT count(*)::int AS n FROM project_surfaces WHERE project_id = $1`,
        [p[0].id],
      );
      const { rows: cu } = await pool.query(
        `SELECT count(*)::int AS n FROM community_users WHERE platform_user_id = ANY($1)`,
        [[memberA, memberB]],
      );
      return {
        projects: p.length,
        projectMembers: pm[0].n,
        projectSurfaces: ps[0].n,
        communityUsers: cu[0].n,
      };
    };

    const first = await runOnce();
    assert.match(first ?? '', /registered as member/, 'the first run must actually register new members');
    const before = await countRows();

    const second = await runOnce();
    assert.doesNotMatch(second ?? '', /registered as member/, 'the second run must not re-register anyone');
    assert.match(
      second ?? '',
      new RegExp(`discord:${memberA}: registration already existed; project already existed`),
    );
    assert.match(second ?? '', /conversation: already bound/);
    const after = await countRows();
    assert.deepEqual(after, before, 'row counts must be unchanged across an idempotent re-run');
  },
);

// --- team_setup welcome DM parity (issue #1065) -----------------------------
// add_member sends a welcome DM (notifyMemberApproved) to every newly
// registered member (issue #556's MEMBER_DM_FAILED_NOTE); team_setup's own
// registration step (above) never called it. These tests cover the
// delivery-parity fix: exactly one DM per NEWLY registered target, none for
// an already-existing member, best-effort (a DM failure never blocks
// registration/project-add/bind), and one aggregate failure note mirroring
// add_member's single MEMBER_DM_FAILED_NOTE.

test(
  'team_setup sends exactly one welcome DM per newly-registered member, and none for an already-existing member (issue #1065)',
  { skip },
  async () => {
    const conv = `${RUN}-team-setup-dm-count`;
    const slug = `${RUN}-team-setup-dm-count`;
    const existingA = teamSetupMemberId();
    const existingB = teamSetupMemberId();
    const existingC = teamSetupMemberId();
    const freshA = teamSetupMemberId();
    const freshB = teamSetupMemberId();
    for (const id of [existingA, existingB, existingC]) {
      await upsertMember({ platform: 'discord', userId: id, role: 'member', addedBy: 'test' });
    }

    const dmCalls: string[] = [];
    const adapter = stubAdapter(async (userId) => {
      dmCalls.push(userId);
    });
    const adminId = 'team-setup-dm-count-admin';
    const caller = {
      platform: 'discord' as const,
      userId: adminId,
      userName: 'Admin',
      role: 'admin' as const,
      conversationId: conv,
    };
    const server = buildToolServer(caller, adapter);
    const registeredTool = (
      server.instance as unknown as {
        _registeredTools: Record<
          string,
          {
            handler: (
              args: object,
            ) => Promise<{ content: Array<{ type: string; text: string }>; isError?: boolean }>;
          }
        >;
      }
    )._registeredTools['team_setup'];

    try {
      const result = await registeredTool.handler({
        slug,
        name: 'DM Count Team',
        members: [existingA, existingB, existingC, freshA, freshB],
      });
      assert.equal(result.isError, false);

      const pending = takePendingAction('discord', conv, adminId);
      assert.ok(pending);
      await pending?.execute();

      assert.equal(dmCalls.length, 2, 'exactly one welcome DM per newly-registered member');
      assert.deepEqual(
        new Set(dmCalls),
        new Set([freshA, freshB]),
        'only the newly-registered members receive a welcome DM',
      );
    } finally {
      await pool.query(
        `DELETE FROM community_users WHERE platform = 'discord' AND platform_user_id = ANY($1::text[])`,
        [[existingA, existingB, existingC, freshA, freshB]],
      );
    }
  },
);

