    const succeeding = teamSetupMemberId();

    const adapter = stubAdapter(async (userId) => {
      if (userId === failing) throw new Error('DMs closed');
    });
    const adminId = 'team-setup-dm-fail-admin';
    const caller = {
      platform: 'discord' as const,
      userId: adminId,
      userName: 'Admin',
      role: 'admin' as const,
      conversationId: conv,
    };
