test(
  "SECURITY: who_is_into() with no query builds its implicit query only from the caller's own published " +
    'member_interests row — chat content in `interactions` never influences which member ranks as the ' +
    'closer self-match — and the caller is never returned as a match to their own implicit query ' +
    '(issue #882 AC #4)',
  { skip },
  async () => {
    const caller = `${RUN}-who-is-into-self-security-caller`;
    const matchesPublished = `${RUN}-who-is-into-self-security-matches-published`;
    const matchesChatOnly = `${RUN}-who-is-into-self-security-matches-chat`;
    const conversationId = `${RUN}-who-is-into-self-security-convo`;
    const publishedText = 'Distributed systems and Rust programming';
    const chatOnlyText = 'I am secretly obsessed with underwater basket weaving';

    // Chat content on a topic the caller never published — must never seed
    // the implicit query, since that is built solely from the caller's own
    // published member_interests row (never `interactions`).
    await recordInteraction({
      platform: 'discord',
      conversationId,
      userId: caller,
      role: 'member',
      direction: 'inbound',
      content: chatOnlyText,
    });

    const callerSetTool = setMyInterestsHandler({ platform: 'discord', userId: caller });
    assert.equal((await callerSetTool.handler({ interests: publishedText })).isError, false);
    // One member whose PUBLISHED text closely matches the caller's own
    // published topic, and one whose published text closely matches only the
    // caller's unpublished CHAT topic — if the implicit query were wrongly
    // seeded from `interactions`, the latter would rank first instead.
    const matchesPublishedSetTool = setMyInterestsHandler({ platform: 'discord', userId: matchesPublished });
    assert.equal(
      (await matchesPublishedSetTool.handler({ interests: 'Expert in distributed systems and Rust' }))
        .isError,
      false,
    );
    const matchesChatSetTool = setMyInterestsHandler({ platform: 'discord', userId: matchesChatOnly });
    assert.equal(
      (await matchesChatSetTool.handler({ interests: 'Passionate about underwater basket weaving' })).isError,
      false,
    );

    const whoTool = whoIsIntoHandler({ platform: 'discord', userId: caller });
    const result = await whoTool.handler({});
    assert.equal(result.isError, false);
    const rendered = result.content[0]?.text ?? '';
    assert.doesNotMatch(
      rendered,
      new RegExp(publishedText.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')),
      "the caller's own row must never appear in their own self-match results",
    );
    const publishedMatchIndex = rendered.indexOf('Expert in distributed systems and Rust');
    const chatMatchIndex = rendered.indexOf('Passionate about underwater basket weaving');
    assert.ok(publishedMatchIndex >= 0, 'the member matching the published topic must appear');
    assert.ok(
      chatMatchIndex < 0 || publishedMatchIndex < chatMatchIndex,
      'the member matching the published topic must rank ahead of the member matching only the unpublished chat topic',
    );

    await pool.query(`DELETE FROM member_interests WHERE platform = 'discord' AND user_id = ANY($1)`, [
      [caller, matchesPublished, matchesChatOnly],
    ]);
    await pool.query(`DELETE FROM interactions WHERE user_id = $1`, [caller]);
  },
);

test(
  "who_is_into mine:true returns exactly the caller's own published interests text, with a distinct empty-state message, and leaves mine omitted/false byte-identical to today (issue #1022 AC #1, #2, #5)",
  { skip },
  async () => {
    const caller = `${RUN}-who-is-into-mine-caller`;
    const setTool = setMyInterestsHandler({ platform: 'discord', userId: caller });
    const whoTool = whoIsIntoHandler({ platform: 'discord', userId: caller });

    const noneYet = await whoTool.handler({ mine: true });
    assert.equal(noneYet.isError, false);
    assert.match(noneYet.content[0]?.text ?? '', /haven't published interests yet/i);

    const published = await setTool.handler({ interests: 'Recall-my-own interests text' });
    assert.equal(published.isError, false);

    const mine = await whoTool.handler({ mine: true });
    assert.equal(mine.isError, false);
    assert.match(mine.content[0]?.text ?? '', /Recall-my-own interests text/);

    // AC #5: mine omitted/false stays byte-identical to today's existing
    // no-query self-match path (the caller now has a published row).
    const omitted = await whoTool.handler({});
    const explicitFalse = await whoTool.handler({ mine: false });
    assert.equal(explicitFalse.content[0]?.text, omitted.content[0]?.text);
    assert.doesNotMatch(
      omitted.content[0]?.text ?? '',
      /Recall-my-own interests text/,
      "the existing no-query path excludes the caller's own row (issue #882) — mine:true must not have changed that",
    );

    await pool.query(`DELETE FROM member_interests WHERE platform = 'discord' AND user_id = $1`, [caller]);
  },
);

test(
  "SECURITY: who_is_into({ mine: true }) for caller A never returns caller B's interests, even when B has a published row and A does not (issue #1022 AC #3)",
  { skip },
  async () => {
    const callerA = `${RUN}-who-is-into-mine-caller-a`;
    const callerB = `${RUN}-who-is-into-mine-caller-b`;
    const bSetTool = setMyInterestsHandler({ platform: 'discord', userId: callerB });
    assert.equal(
      (await bSetTool.handler({ interests: 'must never leak into caller A mine:true results' })).isError,
      false,
    );

    const aWhoTool = whoIsIntoHandler({ platform: 'discord', userId: callerA });
    const aMine = await aWhoTool.handler({ mine: true });
    assert.match(
      aMine.content[0]?.text ?? '',
      /haven't published interests yet/i,
      "caller A has no published row of their own, regardless of caller B's",
    );
    assert.doesNotMatch(aMine.content[0]?.text ?? '', /must never leak into caller A/);

    await pool.query(`DELETE FROM member_interests WHERE platform = 'discord' AND user_id = $1`, [callerB]);
  },
);

test(
  "SECURITY: who_is_into mine:true ignores a supplied query and draws its result exclusively from the caller's own published interests, never falling through to the public search path (issue #1022 AC #4)",
  { skip },
  async () => {
    const ownerId = `${RUN}-who-is-into-mine-ignores-query`;
    const otherId = `${RUN}-who-is-into-mine-ignores-query-other`;
    const ownerSetTool = setMyInterestsHandler({ platform: 'discord', userId: ownerId });
    const otherSetTool = setMyInterestsHandler({ platform: 'discord', userId: otherId });
    const whoTool = whoIsIntoHandler({ platform: 'discord', userId: ownerId });

    // The caller's own published text deliberately does NOT match the query
    // below, so if mine:true fell through to the public search path it would
    // be excluded (or replaced by the other member's matching row).
    assert.equal((await ownerSetTool.handler({ interests: 'Unrelated own interests text' })).isError, false);
    assert.equal(
      (await otherSetTool.handler({ interests: 'a gizmo project matching the query below' })).isError,
      false,
    );

    const result = await whoTool.handler({ mine: true, query: 'gizmo' });
    const resultText = result.content[0]?.text ?? '';
    assert.match(resultText, /Unrelated own interests text/, "the caller's own text is still shown");
    assert.doesNotMatch(
      resultText,
      /gizmo/,
      "another member's interests must never appear, even though they match the supplied query",
    );

    await pool.query(`DELETE FROM member_interests WHERE platform = 'discord' AND user_id = ANY($1)`, [
      [ownerId, otherId],
    ]);
  },
);

// share_project / list_projects (issue #646): the member-declared project
// showcase — the second instance of #634's self-declared-member-table
// pattern. share_project is self-scoped write (rate-capped, per-member
// capped, upsert-by-name, folds removal into a `remove` flag); list_projects
// is the read counterpart (most-recent or embedding-similarity).
function shareProjectHandler(caller: {
  platform: 'discord' | 'whatsapp';
  userId: string;
  userName?: string;
  role?: 'member' | 'guest' | 'admin' | 'super_admin';
  conversationId?: string;
}) {
  const adapter = stubAdapter(async () => {});
  const server = buildToolServer(
    {
      platform: caller.platform,
      userId: caller.userId,
      userName: caller.userName ?? 'Member',
      role: caller.role ?? 'member',
      conversationId: caller.conversationId ?? 'convo-share-project',
    },
    adapter,
  );
  return (
    server.instance as unknown as {
      _registeredTools: Record<
        string,
        {
          handler: (args: {
            name: string;
            description?: string;
            link?: string;
            remove?: boolean;
            seekingCollaborators?: boolean;
          }) => Promise<{ content: Array<{ type: string; text: string }>; isError?: boolean }>;
        }
      >;
    }
  )._registeredTools['share_project'];
}

function listProjectsHandler(caller: {
  platform: 'discord' | 'whatsapp';
  userId: string;
  userName?: string;
  role?: 'member' | 'guest' | 'admin' | 'super_admin';
  conversationId?: string;
}) {
  const adapter = stubAdapter(async () => {});
  const server = buildToolServer(
    {
      platform: caller.platform,
      userId: caller.userId,
      userName: caller.userName ?? 'Member',
      role: caller.role ?? 'member',
      conversationId: caller.conversationId ?? 'convo-list-projects',
    },
    adapter,
  );
  return (
    server.instance as unknown as {
      _registeredTools: Record<
        string,
        {
          handler: (args: {
            query?: string;
            seekingCollaborators?: boolean;
            mine?: boolean;
          }) => Promise<{ content: Array<{ type: string; text: string }>; isError?: boolean }>;
        }
      >;
    }
  )._registeredTools['list_projects'];
}

// --- issue #1105: list_projects/who_is_into honour a standing 'mi' language preference ---

test("formatListProjectsEmptyText/formatWhoIsIntoEmptyText render the te reo Māori variant for every kind when language is 'mi', and the exact pre-existing English string for 'auto'/'en' otherwise (issue #1105)", () => {
  for (const language of ['auto', 'en'] as const) {
    assert.equal(
      formatListProjectsEmptyText('mine', language),
      "You haven't shared any projects yet — call share_project to add one.",
    );
    assert.equal(
      formatListProjectsEmptyText('seeking', language),
      'No projects are currently looking for collaborators.',
    );
    assert.equal(formatListProjectsEmptyText('query', language), 'No shared projects match that.');
    assert.equal(
      formatListProjectsEmptyText('none', language),
      'No projects have been shared yet — call share_project to add one.',
    );
    assert.equal(
      formatWhoIsIntoEmptyText('noProfile', language),
      "You haven't published interests yet — call set_my_interests first, then who_is_into with no " +
        'topic will search using your own published interests.',
    );
    assert.equal(
      formatWhoIsIntoEmptyText('query', language),
      'No members have published interests matching that yet.',
    );
    assert.equal(
      formatWhoIsIntoEmptyText('selfNoMatch', language),
      'No other members have published interests matching yours yet.',
    );
  }

  for (const kind of ['mine', 'seeking', 'query', 'none'] as const) {
    assert.notEqual(
      formatListProjectsEmptyText(kind, 'mi'),
      formatListProjectsEmptyText(kind, 'en'),
      `list_projects' '${kind}' empty state must actually differ between 'mi' and 'en'`,
    );
  }
  for (const kind of ['noProfile', 'query', 'selfNoMatch'] as const) {
    assert.notEqual(
      formatWhoIsIntoEmptyText(kind, 'mi'),
      formatWhoIsIntoEmptyText(kind, 'en'),
      `who_is_into's '${kind}' empty state must actually differ between 'mi' and 'en'`,
    );
  }
});

// --- issue #1163: set_helper_availability/find_helper/share_project/request_project_connection honour a standing 'mi' language preference ---

test("formatSetHelperAvailabilityText/formatFindHelperText/formatShareProjectText/formatRequestProjectConnectionText render the te reo Māori variant for every outcome when language is 'mi', and the exact pre-existing English string for 'auto'/'en' otherwise (issue #1163)", () => {
  for (const language of ['auto', 'en'] as const) {
    assert.equal(
      formatSetHelperAvailabilityText('disabled', 3, language),
      'Peer-help handoff is not enabled on this server.',
    );
    assert.equal(
      formatSetHelperAvailabilityText('noProfile', 3, language),
      "You don't have published interests yet — call set_my_interests first, then " +
        'set_helper_availability can turn on notifications for topics matching them.',
    );
    assert.equal(
      formatSetHelperAvailabilityText('optedIn', 3, language),
      "You'll now be notified (at most 3 times a week) when " +
        "another member's find_helper topic matches your published interests.",
    );
    assert.equal(
      formatSetHelperAvailabilityText('optedOut', 3, language),
      "You won't be notified for find_helper requests anymore.",
    );

    assert.equal(
      formatFindHelperText('disabled', 5, language),
      'Peer-help handoff is not enabled on this server.',
    );
    assert.equal(
      formatFindHelperText('dailyCap', 5, language),
      "You've hit today's ask-for-help limit (5). Try again tomorrow.",
    );
    assert.equal(
      formatFindHelperText('matched', 5, language),
      'Reached out to someone who may be able to help — hang tight.',
    );
    assert.equal(
      formatFindHelperText('noMatch', 5, language),
      'No one available to help with that right now.',
    );

    assert.equal(
      formatShareProjectText({ kind: 'missingDescription' }, language),
      'A description is required to share or edit a project.',
    );
    assert.equal(
      formatShareProjectText({ kind: 'cap', limit: 10 }, language),
      'You already have 10 shared projects — remove one first (share_project with remove: true) before ' +
        'adding another.',
    );
    assert.equal(
      formatShareProjectText({ kind: 'rateLimit', limit: 3 }, language),
      "You've already shared 3 new projects in the last 24 hours. Please wait before sharing another.",
    );
    assert.equal(
      formatShareProjectText({ kind: 'removed', name: 'Foo' }, language),
      'Removed "Foo" from the project showcase.',
    );
    assert.equal(
      formatShareProjectText({ kind: 'notFound', name: 'Foo' }, language),
      'You don\'t have a shared project named "Foo".',
    );
    assert.equal(
      formatShareProjectText({ kind: 'created', name: 'Foo' }, language),
      'Shared "Foo" — other members can find it with list_projects.',
    );
    assert.equal(formatShareProjectText({ kind: 'updated', name: 'Foo' }, language), 'Updated "Foo".');

    assert.equal(
      formatRequestProjectConnectionText({ kind: 'dailyCap', limit: 5 }, language),
      "You've hit today's connection-request limit (5). Try again tomorrow.",
    );
    assert.equal(formatRequestProjectConnectionText('notFound', language), 'No active project with that id.');
    assert.equal(
      formatRequestProjectConnectionText('notSeeking', language),
      'That project is not currently looking for collaborators.',
    );
    assert.equal(
      formatRequestProjectConnectionText('selfMatch', language),
      "You can't request to connect with your own project.",
    );
    assert.equal(
      formatRequestProjectConnectionText('ownerUnreachable', language),
      "That project's owner can't be reached on this deployment right now.",
    );
    assert.equal(
      formatRequestProjectConnectionText('ownerCapped', language),
      "That project's owner can't receive new connection requests right now.",
    );
    assert.equal(
      formatRequestProjectConnectionText('sent', language),
      'Reached out to the project owner — hang tight.',
    );
  }

  for (const outcome of ['disabled', 'noProfile', 'optedIn', 'optedOut'] as const) {
    assert.notEqual(
      formatSetHelperAvailabilityText(outcome, 3, 'mi'),
      formatSetHelperAvailabilityText(outcome, 3, 'en'),
      `set_helper_availability's '${outcome}' must actually differ between 'mi' and 'en'`,
    );
  }
  for (const outcome of ['disabled', 'dailyCap', 'matched', 'noMatch'] as const) {
    assert.notEqual(
      formatFindHelperText(outcome, 5, 'mi'),
      formatFindHelperText(outcome, 5, 'en'),
      `find_helper's '${outcome}' must actually differ between 'mi' and 'en'`,
    );
  }
  const shareProjectOutcomes = [
    { kind: 'missingDescription' as const },
    { kind: 'cap' as const, limit: 10 },
    { kind: 'rateLimit' as const, limit: 3 },
    { kind: 'removed' as const, name: 'Foo' },
    { kind: 'notFound' as const, name: 'Foo' },
    { kind: 'created' as const, name: 'Foo' },
    { kind: 'updated' as const, name: 'Foo' },
  ];
  for (const outcome of shareProjectOutcomes) {
    assert.notEqual(
      formatShareProjectText(outcome, 'mi'),
      formatShareProjectText(outcome, 'en'),
      `share_project's '${outcome.kind}' must actually differ between 'mi' and 'en'`,
    );
  }
  const requestProjectConnectionOutcomes = [
    { kind: 'dailyCap' as const, limit: 5 },
    'notFound' as const,
    'notSeeking' as const,
    'selfMatch' as const,
    'ownerUnreachable' as const,
    'ownerCapped' as const,
    'sent' as const,
  ];
  for (const outcome of requestProjectConnectionOutcomes) {
    assert.notEqual(
      formatRequestProjectConnectionText(outcome, 'mi'),
      formatRequestProjectConnectionText(outcome, 'en'),
      `request_project_connection's '${typeof outcome === 'string' ? outcome : outcome.kind}' must actually ` +
        "differ between 'mi' and 'en'",
    );
  }
});

