test(
  "SECURITY: response_latency's reply is exactly the fixed label plus count/median/p90 — never a user id, display name, or message excerpt (acceptance criterion 7)",
  { skip },
  async () => {
    const conversationId = `${RUN}-response-latency-content-convo`;
    const secretUserId = `${RUN}-response-latency-SECRET-USER-ID`;
    const secretContent = 'SECRET-QUESTION-CONTENT-NEVER-SHOWN-response-latency';
    const now = new Date();

    await pool.query(
      `INSERT INTO interactions
         (platform, conversation_id, user_id, role, direction, content, addressed_to_bot, created_at)
       VALUES ('discord',$1,$2,'member','inbound',$3,true,$4)`,
      [conversationId, secretUserId, secretContent, new Date(now.getTime() - 12_000)],
    );
    await pool.query(
      `INSERT INTO interactions
         (platform, conversation_id, user_id, role, direction, content, meta, created_at)
       VALUES ('discord',$1,'bot','member','outbound','the reply text itself',$2,$3)`,
      [conversationId, JSON.stringify({ replyToUserId: secretUserId }), now],
    );

    try {
      const server = buildToolServer(
        {
          platform: 'discord' as const,
          userId: `${RUN}-response-latency-content-admin`,
          userName: 'Admin',
          role: 'admin' as const,
          conversationId,
        },
        stubAdapter(async () => {}),
      );
      const out = (await responseLatencyToolFrom(server.instance).handler({})).content[0]?.text ?? '';
      assert.match(
        out,
        /^⏱️ Response latency \(last 7d\): \d+ replies, median \d+s, p90 \d+s$/,
        'the reply must be exactly the fixed label plus three aggregate numbers',
      );
      assert.ok(
        !out.includes(secretUserId) && !out.includes(secretContent) && !out.includes('the reply text itself'),
        'SECURITY: response_latency must never render a user id, display name, or message excerpt',
      );
    } finally {
      await pool.query(`DELETE FROM interactions WHERE conversation_id = $1`, [conversationId]);
    }
  },
);

// Pairing/scope fix, issue #911 — adds an optional `scope` argument
// ('all' | 'auto_answer' | 'mention') to response_latency.

test("SECURITY: response_latency rejects a scope value outside the enum at the zod schema boundary, never silently coercing it to 'all' (acceptance criterion 4)", () => {
  const adapter = stubAdapter(async () => {});
  const caller = {
    platform: 'discord' as const,
    userId: 'admin-1',
    userName: 'Admin',
    role: 'admin' as const,
    conversationId: 'convo-1',
  };
  const server = buildToolServer(caller, adapter);
  const registeredTool = (
    server.instance as unknown as {
      _registeredTools: Record<string, { inputSchema: { safeParse: (v: unknown) => { success: boolean } } }>;
    }
  )._registeredTools['response_latency'];

  assert.equal(
    registeredTool.inputSchema.safeParse({ scope: 'mentions' }).success,
    false,
    'a scope value outside the enum must fail validation, never reach responseLatencyStats',
  );
  for (const scope of ['all', 'auto_answer', 'mention']) {
    assert.equal(registeredTool.inputSchema.safeParse({ scope }).success, true, `${scope} is allow-listed`);
  }
  assert.equal(
    registeredTool.inputSchema.safeParse({}).success,
    true,
    'scope stays optional, defaulting to all',
  );
});

test(
  "SECURITY: response_latency's scope argument never widens data access — every scope value stays within callerScope() (acceptance criterion 6)",
  { skip },
  async () => {
    const inScopeConvo = `${RUN}-response-latency-scope-widen-in`;
    const outOfScopeConvo = `${RUN}-response-latency-scope-widen-out`;
    const inScopeAutoUser = `${RUN}-response-latency-scope-widen-in-auto-user`;
    const inScopeMentionUser = `${RUN}-response-latency-scope-widen-in-mention-user`;
    const outOfScopeAutoUser = `${RUN}-response-latency-scope-widen-out-auto-user`;
    const outOfScopeMentionUser = `${RUN}-response-latency-scope-widen-out-mention-user`;
    const now = new Date();

    async function seedPair(
      conversationId: string,
      autoUser: string,
      mentionUser: string,
      autoDeltaMs: number,
      mentionDeltaMs: number,
    ) {
      // Auto-answer pair: ambient (non-addressed) trigger + autoAnswer reply.
      await pool.query(
        `INSERT INTO interactions (platform, conversation_id, user_id, role, direction, content, addressed_to_bot, created_at)
         VALUES ('discord',$1,$2,'member','inbound','ambient post',false,$3)`,
        [conversationId, autoUser, new Date(now.getTime() - autoDeltaMs)],
      );
      await pool.query(
        `INSERT INTO interactions (platform, conversation_id, user_id, role, direction, content, meta, created_at)
         VALUES ('discord',$1,'bot','member','outbound','auto-answer reply',$2,$3)`,
        [conversationId, JSON.stringify({ replyToUserId: autoUser, autoAnswer: true }), now],
      );
      // Mention pair: addressed trigger + plain reply.
      await pool.query(
        `INSERT INTO interactions (platform, conversation_id, user_id, role, direction, content, addressed_to_bot, created_at)
         VALUES ('discord',$1,$2,'member','inbound','addressed question',true,$3)`,
        [conversationId, mentionUser, new Date(now.getTime() - mentionDeltaMs)],
      );
      await pool.query(
        `INSERT INTO interactions (platform, conversation_id, user_id, role, direction, content, meta, created_at)
         VALUES ('discord',$1,'bot','member','outbound','mention reply',$2,$3)`,
        [conversationId, JSON.stringify({ replyToUserId: mentionUser }), now],
      );
    }

    // Deliberately distinguishable deltas so a leak is unmistakable.
    await seedPair(inScopeConvo, inScopeAutoUser, inScopeMentionUser, 5_000, 7_000);
    await seedPair(outOfScopeConvo, outOfScopeAutoUser, outOfScopeMentionUser, 500_000, 700_000);

    try {
      const expectedByScope = { all: [2, 6], auto_answer: [1, 5], mention: [1, 7] } as const;
      for (const scope of ['all', 'auto_answer', 'mention'] as const) {
        const server = buildToolServer(
          {
            platform: 'discord' as const,
            userId: `${RUN}-response-latency-scope-widen-admin`,
            userName: 'Admin',
            role: 'admin' as const,
            conversationId: inScopeConvo,
          },
          stubAdapter(async () => {}),
        );
        const out =
          (await responseLatencyToolFrom(server.instance).handler({ scope })).content[0]?.text ?? '';
        const [expectedCount, expectedMedian] = expectedByScope[scope];
        assert.match(
          out,
          new RegExp(
            `^⏱️ Response latency \\(last 7d\\): ${expectedCount} replies, median ${expectedMedian}s, p90 \\d+s$`,
          ),
          `SECURITY: scope=${scope} must reflect only the in-scope conversation's pairs`,
        );
        assert.ok(
          !out.includes('500') && !out.includes('700'),
          `SECURITY: scope=${scope} must never surface the out-of-scope conversation's delta`,
        );
      }
    } finally {
      await pool.query(`DELETE FROM interactions WHERE conversation_id = ANY($1)`, [
        [inScopeConvo, outOfScopeConvo],
      ]);
    }
  },
);

test(
  "SECURITY: response_latency's reply stays exactly the fixed label plus count/median/p90 (or the fixed empty message) under every scope value — never a user id, display name, or message excerpt (acceptance criterion 7)",
  { skip },
  async () => {
    const conversationId = `${RUN}-response-latency-content-scope-convo`;
    const secretUserId = `${RUN}-response-latency-content-scope-SECRET-USER-ID`;
    const secretContent = 'SECRET-QUESTION-CONTENT-NEVER-SHOWN-response-latency-scope';
    const now = new Date();

    // A single auto-answer pair: visible under 'all'/'auto_answer', absent under 'mention'.
    await pool.query(
      `INSERT INTO interactions
         (platform, conversation_id, user_id, role, direction, content, addressed_to_bot, created_at)
       VALUES ('discord',$1,$2,'member','inbound',$3,false,$4)`,
      [conversationId, secretUserId, secretContent, new Date(now.getTime() - 12_000)],
    );
    await pool.query(
      `INSERT INTO interactions
         (platform, conversation_id, user_id, role, direction, content, meta, created_at)
       VALUES ('discord',$1,'bot','member','outbound','the reply text itself',$2,$3)`,
      [conversationId, JSON.stringify({ replyToUserId: secretUserId, autoAnswer: true }), now],
    );

    try {
      for (const scope of ['all', 'auto_answer', 'mention'] as const) {
        const server = buildToolServer(
          {
            platform: 'discord' as const,
            userId: `${RUN}-response-latency-content-scope-admin`,
            userName: 'Admin',
            role: 'admin' as const,
            conversationId,
          },
          stubAdapter(async () => {}),
        );
        const out =
          (await responseLatencyToolFrom(server.instance).handler({ scope })).content[0]?.text ?? '';
        assert.match(
          out,
          /^⏱️ Response latency \(last 7d\): (\d+ replies, median \d+s, p90 \d+s|not enough data yet\.)$/,
          `scope=${scope} reply must be exactly the fixed label plus aggregate numbers, or the fixed empty message`,
        );
        assert.ok(
          !out.includes(secretUserId) &&
            !out.includes(secretContent) &&
            !out.includes('the reply text itself'),
          `SECURITY: scope=${scope} must never render a user id, display name, or message excerpt`,
        );
      }
    } finally {
      await pool.query(`DELETE FROM interactions WHERE conversation_id = $1`, [conversationId]);
    }
  },
);

test(
  'admin_activity resolves display names via the community_users->server_roster precedence, falls back to the raw platform user id for an unknown actor, and never renders admin_audit.params content (issue #488)',
  { skip },
  async () => {
    const knownActor = `${RUN}-aa-known-actor`;
    const unknownActor = `${RUN}-aa-unknown-actor`;
    const sentinel = 'SENTINEL-FREE-TEXT-REASON-NEVER-SHOWN-ADMIN-ACTIVITY';

    await upsertMember({
      platform: 'discord',
      userId: knownActor,
      role: 'admin',
      addedBy: `${RUN}-actor`,
      displayName: `${RUN} Known Actor`,
    });
    await recordAdminAction({
      platform: 'discord',
      actorUserId: knownActor,
      actionKind: 'warn_user',
      params: { reason: sentinel },
      result: 'warned',
      success: true,
    });
    await recordAdminAction({
      platform: 'discord',
      actorUserId: unknownActor,
      actionKind: 'timeout_user',
      result: 'timed out',
      success: true,
    });

    const adapter = stubAdapter(async () => {});
    const handler = adminActivityHandler({ userId: `${RUN}-aa-actor2`, adapter });

    try {
      const result = await handler.handler({ days: 1 });
      const out = result.content[0]?.text ?? '';

      assert.match(
        out,
        new RegExp(`${RUN} Known Actor \\(discord\\): 1 actions \\(1 success / 0 failed\\)`),
        'the known actor is rendered with its resolved display name',
      );
      assert.match(
        out,
        new RegExp(`${unknownActor} \\(discord\\): 1 actions \\(1 success / 0 failed\\)`),
        'an actor with no resolvable name falls back to the raw platform user id',
      );
      assert.ok(!out.includes(sentinel), 'admin_audit.params content must never appear in the reply');
    } finally {
      await pool.query(`DELETE FROM admin_audit WHERE actor_user_id = ANY($1)`, [[knownActor, unknownActor]]);
      await pool.query(`DELETE FROM community_users WHERE platform_user_id = $1`, [knownActor]);
    }
  },
);

test(
  'SECURITY: reserveVoiceTranscriptionSlot keys are platform-qualified — a WhatsApp id and a Discord id ' +
    'that happen to collide never share an hourly transcription quota (issue #732)',
  () => {
    const collidingId = `${RUN}-voice-collide`;
    const limit = 1;
    assert.equal(
      reserveVoiceTranscriptionSlot(`whatsapp:${collidingId}`, limit),
      true,
      'the WhatsApp-qualified key gets its own first slot',
    );
    assert.equal(
      reserveVoiceTranscriptionSlot(`discord:${collidingId}`, limit),
      true,
      'a Discord id colliding with the WhatsApp bare id must NOT share the WhatsApp quota',
    );
    assert.equal(
      reserveVoiceTranscriptionSlot(`whatsapp:${collidingId}`, limit),
      false,
      'the WhatsApp quota is independently exhausted after its own single slot',
    );
    assert.equal(
      reserveVoiceTranscriptionSlot(`discord:${collidingId}`, limit),
      false,
      'the Discord quota is independently exhausted after its own single slot',
    );
  },
);

test(
  'merge_knowledge merges the confirmed pair via the tool handler and records the pre-merge title/content of the deleted entry in admin_audit (issue #886 acceptance criteria 1 and 5)',
  { skip },
  async () => {
    const scope = `${RUN}-merge-knowledge-tool-scope`;
    const adapter = stubAdapter(async () => {});
    const caller = {
      platform: 'discord' as const,
      userId: `${RUN}-merge-knowledge-tool-admin`,
      userName: 'Admin',
      role: 'admin' as const,
      conversationId: `${RUN}-merge-knowledge-tool-convo`,
    };
    const server = buildToolServer(caller, adapter);
    const tools = (
      server.instance as unknown as {
        _registeredTools: Record<
          string,
          {
            handler: (
              args: Record<string, unknown>,
            ) => Promise<{ content: Array<{ text: string }>; isError?: boolean }>;
          }
        >;
      }
    )._registeredTools;

    const { id: keepId } = await saveKnowledge({ title: 'Keep me', content: 'Survivor content.', scope });
    const { id: mergeId } = await saveKnowledge({
      title: 'Retire me',
      content: 'Loser content, must be recorded pre-delete.',
      scope,
    });

    const result = await tools['merge_knowledge'].handler({ keepId, mergeId });
    assert.equal(result.isError, false);
    assert.match(result.content[0]?.text ?? '', /CONFIRM/);

    const { rows: beforeConfirm } = await pool.query(
      `SELECT count(*)::int AS n FROM admin_audit WHERE action_kind = 'merge_knowledge'`,
    );

    const pending = takePendingAction('discord', caller.conversationId, caller.userId);
    assert.ok(pending, 'must register a pending action');
    const execResult = await pending?.execute();
    assert.match(execResult ?? '', new RegExp(`Merged knowledge entry #${mergeId} into #${keepId}`));

    const goneRow = await pool.query(`SELECT 1 FROM knowledge WHERE id = $1`, [mergeId]);
    assert.equal(goneRow.rows.length, 0, 'mergeId is deleted once confirmed');

    const { rows: afterConfirm } = await pool.query(
      `SELECT count(*)::int AS n FROM admin_audit WHERE action_kind = 'merge_knowledge'`,
    );
    assert.equal(
      afterConfirm[0].n,
      beforeConfirm[0].n + 1,
      'exactly one new admin_audit row for the confirmed merge',
    );
    const { rows: auditRows } = await pool.query(
      `SELECT params FROM admin_audit WHERE action_kind = 'merge_knowledge' ORDER BY id DESC LIMIT 1`,
    );
    const params = auditRows[0].params as {
      keepId: number;
      mergeId: number;
      mergedTitle: string | null;
      mergedContent: string;
    };
    assert.equal(params.keepId, keepId);
    assert.equal(params.mergeId, mergeId);
    assert.equal(params.mergedTitle, 'Retire me', "audit row records the deleted entry's pre-merge title");
    assert.equal(
      params.mergedContent,
      'Loser content, must be recorded pre-delete.',
      "audit row records the deleted entry's pre-merge content",
    );

    await pool.query(`DELETE FROM knowledge WHERE id = $1`, [keepId]);
    await pool.query(
      `DELETE FROM admin_audit WHERE action_kind = 'merge_knowledge' AND params->>'keepId' = $1`,
      [String(keepId)],
    );
  },
);

test(
  'SECURITY: merge_knowledge rejects keepId === mergeId and a nonexistent id with zero mutation and no admin_audit success row (issue #886 acceptance criterion 3)',
  { skip },
  async () => {
    const scope = `${RUN}-merge-knowledge-guard-scope`;
    const adapter = stubAdapter(async () => {});
    const caller = {
      platform: 'discord' as const,
      userId: `${RUN}-merge-knowledge-guard-admin`,
      userName: 'Admin',
      role: 'admin' as const,
      conversationId: `${RUN}-merge-knowledge-guard-convo`,
    };
    const server = buildToolServer(caller, adapter);
    const tools = (
      server.instance as unknown as {
        _registeredTools: Record<string, { handler: (args: Record<string, unknown>) => Promise<unknown> }>;
      }
    )._registeredTools;

    const { id } = await saveKnowledge({ title: 'Guarded', content: 'Do not merge me away.', scope });

    await tools['merge_knowledge'].handler({ keepId: id, mergeId: id });
    const sameIdResult = await takePendingAction('discord', caller.conversationId, caller.userId)?.execute();
    assert.match(sameIdResult ?? '', /Failed/);

    await tools['merge_knowledge'].handler({ keepId: id, mergeId: -1 });
    const missingResult = await takePendingAction('discord', caller.conversationId, caller.userId)?.execute();
    assert.match(missingResult ?? '', /Failed/);

    const row = await pool.query(`SELECT title, content FROM knowledge WHERE id = $1`, [id]);
    assert.equal(row.rows.length, 1, 'the guarded row still exists, untouched');
    assert.equal(row.rows[0].title, 'Guarded');
    assert.equal(row.rows[0].content, 'Do not merge me away.');

    const { rows: successRows } = await pool.query(
      `SELECT 1 FROM admin_audit WHERE action_kind = 'merge_knowledge' AND success = true AND params->>'keepId' = $1`,
      [String(id)],
    );
    assert.equal(successRows.length, 0, 'neither rejected call produced a successful admin_audit row');

    await pool.query(`DELETE FROM knowledge WHERE id = $1`, [id]);
    await pool.query(
      `DELETE FROM admin_audit WHERE action_kind = 'merge_knowledge' AND params->>'keepId' = $1`,
      [String(id)],
    );
  },
);
